def is_majority(arr, n, element):
    """
    Return True if `element` occurs more than n/2 times in the sorted array `arr`.
    """
    if n <= 0:
        return False

    # Guard against a mismatched length just in case.
    if n > len(arr):
        n = len(arr)

    def lower_bound(target):
        lo, hi = 0, n
        while lo < hi:
            mid = (lo + hi) // 2
            if arr[mid] < target:
                lo = mid + 1
            else:
                hi = mid
        return lo

    def upper_bound(target):
        lo, hi = 0, n
        while lo < hi:
            mid = (lo + hi) // 2
            if arr[mid] <= target:
                lo = mid + 1
            else:
                hi = mid
        return lo

    first = lower_bound(element)
    last = upper_bound(element)
    count = last - first

    return count * 2 > n


