from typing import List

class Solution:
    def numOfUnplacedFruits(self, fruits: List[int], baskets: List[int]) -> int:
        n = len(baskets)
        size = 1
        while size < n:
            size <<= 1

        tree = [0] * (2 * size)

        for i, cap in enumerate(baskets):
            tree[size + i] = cap

        for i in range(size - 1, 0, -1):
            tree[i] = max(tree[i << 1], tree[i << 1 | 1])

        unplaced = 0

        for fruit in fruits:
            if tree[1] < fruit:
                unplaced += 1
                continue

            node = 1
            while node < size:
                left = node << 1
                if tree[left] >= fruit:
                    node = left
                else:
                    node = left | 1

            tree[node] = 0
            node >>= 1

            while node:
                tree[node] = max(tree[node << 1], tree[node << 1 | 1])
                node >>= 1

        return unplaced
