def is_samepatterns(words, patterns):
    """
    Return True if the sequence in `words` follows the pattern sequence in `patterns`.

    Each pattern token must map to exactly one word, and each word must map to
    exactly one pattern token.
    """
    if len(words) != len(patterns):
        return False

    pattern_to_word = {}
    word_to_pattern = {}

    for word, pattern in zip(words, patterns):
        if pattern in pattern_to_word:
            if pattern_to_word[pattern] != word:
                return False
        else:
            pattern_to_word[pattern] = word

        if word in word_to_pattern:
            if word_to_pattern[word] != pattern:
                return False
        else:
            word_to_pattern[word] = pattern

