class Solution:
    def longestPalindrome(self, s: str, t: str) -> int:
        def get_substrings(x: str):
            result = [""]
            n = len(x)
            for i in range(n):
                for j in range(i + 1, n + 1):
                    result.append(x[i:j])
            return result

        s_substrings = get_substrings(s)
        t_substrings = get_substrings(t)

        ans = 0
        max_possible = len(s) + len(t)

        for a in s_substrings:
            for b in t_substrings:
                length = len(a) + len(b)
                if length <= ans:
                    continue

                candidate = a + b
                if candidate == candidate[::-1]:
                    ans = length
                    if ans == max_possible:
                        return ans

        return ans
