class Solution:
    def assignElements(self, groups: List[int], elements: List[int]) -> List[int]:
        if not groups:
            return []

        max_group = max(groups)
        inf = len(elements)

        # min_index[d] = smallest index of an element equal to d, or inf if none.
        min_index = [inf] * (max_group + 1)

        for i, value in enumerate(elements):
            if value <= max_group and i < min_index[value]:
                min_index[value] = i

        # best[g] = smallest element index that divides g, or inf if none.
        best = [inf] * (max_group + 1)

        for divisor in range(1, max_group + 1):
            idx = min_index[divisor]
            if idx == inf:
                continue

            for multiple in range(divisor, max_group + 1, divisor):
                if idx < best[multiple]:
                    best[multiple] = idx

        return [best[group] if best[group] != inf else -1 for group in groups]
