def set_left_most_unset_bit(n: int) -> int:
    """Return n with its leftmost unset bit set to 1."""
    if n < 0:
        raise ValueError("n must be non-negative")

    bits = bin(n)[2:]
    zero_index = bits.find("0")

    if zero_index == -1:
        return n

    bit_position = len(bits) - 1 - zero_index
    return n | (1 << bit_position)


