class Solution:
    def maxFrequency(self, nums: List[int], k: int) -> int:
        total_k = nums.count(k)
        ans = total_k
        n = len(nums)

        for target in set(nums):
            if target == k:
                continue

            current = 0
            best = 0

            for num in nums:
                if num == target:
                    current += 1
                elif num == k:
                    current -= 1

                if current < 0:
                    current = 0

                if current > best:
                    best = current

            ans = max(ans, total_k + best)
            if ans == n:
                return ans

        return ans
