class Solution:
    def countMentions(self, numberOfUsers: int, events: List[List[str]]) -> List[int]:
        n = numberOfUsers
        mentions = [0] * n
        online = [True] * n
        offline_until = [-1] * n

        parsed_events = []
        for event_type, timestamp, payload in events:
            parsed_events.append((int(timestamp), event_type, payload))

        # Process offline events before message events at the same timestamp.
        parsed_events.sort(key=lambda x: (x[0], 0 if x[1] == "OFFLINE" else 1))

        i = 0
        m = len(parsed_events)

        while i < m:
            current_time = parsed_events[i][0]

            # Users whose offline period has ended are online before any event at this time.
            for user in range(n):
                if offline_until[user] != -1 and offline_until[user] <= current_time:
                    online[user] = True
                    offline_until[user] = -1

            # Process all OFFLINE events at this timestamp.
            while i < m and parsed_events[i][0] == current_time and parsed_events[i][1] == "OFFLINE":
                user_id = int(parsed_events[i][2])
                online[user_id] = False
                offline_until[user_id] = current_time + 60
                i += 1

            # Process all MESSAGE events at this timestamp.
            while i < m and parsed_events[i][0] == current_time:
                mentions_string = parsed_events[i][2]

                for token in mentions_string.split():
                    if token == "ALL":
                        for user in range(n):
                            mentions[user] += 1
                    elif token == "HERE":
                        for user in range(n):
                            if online[user]:
                                mentions[user] += 1
                    else:
                        user_id = int(token[2:])
                        mentions[user_id] += 1

                i += 1

        return mentions
